// Builds the emulator WebView page: firmware/emu/dist (ripar-emu-core.mjs + ripar-emu.mjs + ripar-emu-core.wasm as
// base64) + scripts/emu-bridge.js, inlined into one HTML string, written to src/device/emulator/emu-html.generated.ts.
// Runs on `npm install` (postinstall) and before bundling; never fails the install: without the emulator dist it writes
// a page that says so. The generated file is git-ignored (about 700 KB).
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');
const dist = resolve(root, '../firmware/emu/dist');
const out = join(root, 'src/device/emulator/emu-html.generated.ts');
mkdirSync(dirname(out), { recursive: true });

const files = ['ripar-emu-core.mjs', 'ripar-emu.mjs', 'ripar-emu-core.wasm'].map((f) => join(dist, f));
let html;
let note;
if (files.every((f) => existsSync(f))) {
  const core = readFileSync(files[0], 'utf8').replace(/export\s+default\s+createRiparEmuCore\s*;?\s*$/, '');
  if (/\bexport\s/.test(core.slice(-200))) throw new Error('unexpected export in ripar-emu-core.mjs');
  const wrapper = readFileSync(files[1], 'utf8')
    .replace(/^import\s+createRiparEmuCore\s+from\s+['"]\.\/ripar-emu-core\.mjs['"];?\s*$/m, '')
    .replace(/^export\s+default\s+RiparEmulator\s*;?\s*$/m, '')
    .replace(/^export\s+(const|class|function|let)\s/gm, '$1 ');
  if (/^\s*(import|export)\s/m.test(wrapper)) throw new Error('ripar-emu.mjs: an import / export was left after inlining');
  const wasm = readFileSync(files[2]).toString('base64');
  const bridge = readFileSync(join(here, 'emu-bridge.js'), 'utf8');
  const script = `${core}\n${wrapper}\nconst WASM_B64 = "${wasm}";\n${bridge}`;
  // the script ends up inside <script type="module">: a literal "</script" would close it
  if (/<\/script/i.test(script)) throw new Error('the emulator sources contain </script');
  html =
    '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width">' +
    `<title>Ripar emulator</title></head><body><script type="module">\n${script}\n</script></body></html>`;
  note = `firmware/emu/dist (${Math.round(readFileSync(files[2]).length / 1024)} KB wasm)`;
} else {
  html =
    '<!doctype html><html><body><script>window.ReactNativeWebView&&window.ReactNativeWebView.postMessage(' +
    `JSON.stringify({t:"error",message:"The emulator was not built: firmware/emu/dist is missing (bash firmware/emu/build.sh)."}));` +
    '</script></body></html>';
  note = 'a stub (firmware/emu/dist missing)';
}

writeFileSync(
  out,
  `// GENERATED by scripts/build-emu-html.mjs from ${note}. Do not edit; git-ignored.\n` +
    `export const EMU_HTML: string = ${JSON.stringify(html)};\n`,
);
console.log(`emulator page: ${out} (${Math.round(html.length / 1024)} KB) from ${note}`);
